export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

const STATUS_ORDER: TaskStatus[] = ["todo", "in-progress", "done"];

export class TaskService {
  private readonly tasks: Map<string, Task> = new Map();

  create(title: string, description: string, projectId: string): Task {
    const id = crypto.randomUUID();
    const task: Task = {
      id,
      title,
      description,
      projectId,
      status: "todo",
      assigneeId: null,
    };
    this.tasks.set(id, task);
    return task;
  }

  getById(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (task) => task.projectId === projectId
    );
  }

  update(id: string, title: string, description: string): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) {
      return undefined;
    }
    task.title = title;
    task.description = description;
    return task;
  }

  delete(id: string): boolean {
    return this.tasks.delete(id);
  }

  assign(id: string, assigneeId: string): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) {
      return undefined;
    }
    task.assigneeId = assigneeId;

    eventBus.publish("task.assigned", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
    });

    return task;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) {
      return undefined;
    }

    const oldStatus = task.status;
    const oldIndex = STATUS_ORDER.indexOf(oldStatus);
    const newIndex = STATUS_ORDER.indexOf(newStatus);

    if (newIndex < oldIndex) {
        // Allow resetting to 'todo' from any state, but not moving backwards otherwise.
        if (newStatus !== 'todo') {
            return undefined; // Invalid transition
        }
    }

    task.status = newStatus;

    if (task.assigneeId) {
        eventBus.publish("task.statusChanged", {
            taskId: task.id,
            taskTitle: task.title,
            assigneeId: task.assigneeId,
            oldStatus,
            newStatus,
        });
    }

    return task;
  }
}

